# 初始化触摸控制器
def init_touch():
    """初始化CST816S触摸控制器"""
    try:
        # 根据您的硬件配置调整I2C引脚
        i2c = machine.I2C(0, scl=machine.Pin(6), sda=machine.Pin(7), freq=400000)
        
        touch = CST816S(
            device=i2c,
            reset_pin=machine.Pin(5, machine.Pin.OUT),
            debug=True
        )
        
        # 配置触摸参数
        touch.auto_sleep = False  # 禁用自动休眠以获得更快的响应
        touch.set_long_press_time(2)  # 设置长按时间为2秒
        touch.enable_double_click(True)  # 启用双击检测
        
        print("Touch controller initialized successfully")
        touch.print_debug_info()
        
        return touch
    except Exception as e:
        print(f"Touch initialization failed: {e}")
        return None

# 初始化触摸
