class GestureHandler:
    """手势处理类 - 集成到SquareLine项目"""
    def __init__(self, touch_controller):
        self.touch = touch_controller
        self.last_gesture_check = time.ticks_ms()
        self.gesture_handlers = {}
        self.current_screen = None
        self.keyboard_visible = True
        
    def register_gesture_handler(self, gesture, handler):
        """注册手势处理器"""
        self.gesture_handlers[gesture] = handler
        
    def set_current_screen(self, screen):
        """设置当前屏幕"""
        self.current_screen = screen
        
    def check_gestures(self):
        """检查并处理手势"""
        if self.touch is None:
            return
            
        current_time = time.ticks_ms()
        if time.ticks_diff(current_time, self.last_gesture_check) > 100:  # 每100ms检查一次
            gesture = self.touch.get_gesture()
            if gesture != GESTURE_NONE:
                gesture_name = self.touch.gesture_to_string(gesture)
                print(f"Detected gesture: {gesture_name}")
                
                # 调用注册的手势处理器
                if gesture in self.gesture_handlers:
                    self.gesture_handlers[gesture]()
                else:
                    # 默认手势处理
                    self._handle_default_gesture(gesture)
            
            self.last_gesture_check = current_time
    
    def _handle_default_gesture(self, gesture):
        """默认手势处理"""
        if gesture == GESTURE_SWIPE_LEFT:
            print("Swipe left - navigating back")
        elif gesture == GESTURE_SWIPE_RIGHT:
            print("Swipe right - navigating forward")
        elif gesture == GESTURE_SWIPE_UP:
            print("Swipe up - scrolling up")
        elif gesture == GESTURE_SWIPE_DOWN:
            print("Swipe down - scrolling down")
        elif gesture == GESTURE_SINGLE_CLICK:
            print("Single click - select")
        elif gesture == GESTURE_DOUBLE_CLICK:
            print("Double click - quick action")
        elif gesture == GESTURE_LONG_PRESS:
            print("Long press - context menu")

# 创建手势处理器
