class TouchTaskHandler:
    """触摸任务处理类"""
    def __init__(self, gesture_handler):
        self.gesture_handler = gesture_handler
        self.last_update = time.ticks_ms()
    
    def update(self):
        """更新触摸状态"""
        current_time = time.ticks_ms()
        
        # 每50ms更新一次手势检测（不影响LVGL的主循环性能）
        if time.ticks_diff(current_time, self.last_update) > 50:
            if self.gesture_handler:
                self.gesture_handler.check_gestures()
            self.last_update = current_time

# 创建任务处理器
try:
    th = task_handler.TaskHandler()
    touch_task_handler = TouchTaskHandler(gesture_handler)
    
    # 添加触摸更新到主循环
    def touch_update_task():
        """触摸更新任务"""
        touch_task_handler.update()
    
    # 注册定时任务
    try:
        th.add_periodic_task(50, touch_update_task)  # 每50ms检查一次手势
        print("Touch gesture handler registered successfully")
    except Exception as e:
        print(f"Periodic task registration failed: {e}")
except Exception as e:
    print(f"Task handler initialization failed: {e}")

